import React from "react";
import {Card, type PiCardProps} from "@pihanga2/core";

import {
  Dialog as DialogRoot,
  DialogTrigger,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogBody,
  DialogFooter,
} from "@/components/ui/dialog";
import {Button} from "@/components/ui/button";

import type {PiDialogEvents, PiDialogProps} from "./dialog.types";

export const DialogComponent = (
  props: PiCardProps<PiDialogProps, PiDialogEvents>,
): React.ReactNode => {
  const {
    id,
    trigger,
    content,
    title,
    description,
    open: controlledOpen,
    size,
    variant,
    desktopVariant,
    mobileVariant,
    dismissible,
    hideClose,
    className,
    footer,
    footerCloseButtonText,
    cardName,
    onOpened,
    onClosed,
    onOpenChanged,
  } = props;

  // Apply default for footer close button text
  const effectiveFooterCloseButtonText =
    footerCloseButtonText === undefined ? "Close" : footerCloseButtonText;

  // Internal state for uncontrolled mode
  const [internalOpen, setInternalOpen] = React.useState(false);

  // Use controlled open if provided, otherwise use internal state
  const open = controlledOpen ?? internalOpen;

  // Track previous open state to detect programmatic changes
  const prevControlledOpenRef = React.useRef(controlledOpen);

  React.useEffect(() => {
    // Detect programmatic close via props.open changing from true to false
    if (
      prevControlledOpenRef.current === true &&
      controlledOpen === false &&
      open === false
    ) {
      // This is a programmatic close
      onClosed({id, reason: "programmatic"});
    }
    prevControlledOpenRef.current = controlledOpen;
  }, [controlledOpen, open, id, onClosed]);

  const handleOpenChange = (nextOpen: boolean) => {
    // Update internal state if not controlled
    if (controlledOpen === undefined) {
      setInternalOpen(nextOpen);
    }

    // Emit events
    onOpenChanged({open: nextOpen, id});

    if (nextOpen) {
      onOpened({id});
    } else {
      // When user dismisses (not programmatic), reason is 'user'
      // We only get here from user actions when controlled open is undefined
      // or when the dialog component itself triggers the change
      if (controlledOpen === undefined) {
        onClosed({id, reason: "user"});
      }
    }
  };

  function renderTrigger() {
    if (!trigger) return null;

    // Similar to dropDownMenu: wrap trigger in a DOM element so Radix
    // can attach handlers via asChild even when trigger is a Pihanga card.
    return (
      <span className="inline-flex" data-pihanga-trigger-wrapper>
        <Card cardName={trigger} parentCard={cardName} />
      </span>
    );
  }

  function renderHeader() {
    if (!title && !description) return null;

    return (
      <DialogHeader>
        {title && <DialogTitle>{title}</DialogTitle>}
        {description && <DialogDescription>{description}</DialogDescription>}
      </DialogHeader>
    );
  }

  function renderFooter() {
    // Custom footer card takes precedence
    if (footer) {
      return (
        <DialogFooter className="bg-muted/50">
          <Card cardName={footer} parentCard={cardName} />
        </DialogFooter>
      );
    }

    // Default close button (if not explicitly disabled)
    if (effectiveFooterCloseButtonText !== null) {
      return (
        <DialogFooter className="bg-muted/50">
          <Button variant="outline" onClick={() => handleOpenChange(false)}>
            {effectiveFooterCloseButtonText}
          </Button>
        </DialogFooter>
      );
    }

    // No footer
    return null;
  }

  // Use fixed layout when we have header or footer
  const hasFixedLayout = !!(
    title ||
    description ||
    footer ||
    effectiveFooterCloseButtonText
  );

  return (
    <DialogRoot
      open={open}
      onOpenChange={handleOpenChange}
      desktopVariant={desktopVariant}
      mobileVariant={mobileVariant}
    >
      {trigger && <DialogTrigger asChild>{renderTrigger()}</DialogTrigger>}
      <DialogContent
        data-pihanga={cardName}
        size={size}
        variant={variant === "drawer" ? undefined : variant}
        dismissible={dismissible}
        hideClose={hideClose}
        fixed={hasFixedLayout}
        className={className}
      >
        {renderHeader()}
        <DialogBody>
          <Card cardName={content} parentCard={cardName} />
        </DialogBody>
        {renderFooter()}
      </DialogContent>
    </DialogRoot>
  );
};

import {
  createCardDeclaration,
  createOnAction,
  type PiCardRef,
  registerActions,
} from "@pihanga2/core";

export const PI_DIALOG_CARD = "pi/dialog";

export const Dialog = createCardDeclaration<PiDialogProps, PiDialogEvents>(
  PI_DIALOG_CARD,
);

export const PI_DIALOG_ACTION = registerActions(PI_DIALOG_CARD, [
  "opened",
  "closed",
  "open_changed",
]);

export const onDialogOpened = createOnAction<DialogOpenedEvent>(
  PI_DIALOG_ACTION.OPENED,
);

export const onDialogClosed = createOnAction<DialogClosedEvent>(
  PI_DIALOG_ACTION.CLOSED,
);

export const onDialogOpenChanged = createOnAction<DialogOpenChangedEvent>(
  PI_DIALOG_ACTION.OPEN_CHANGED,
);

export type PiDialogProps = {
  /**
   * Optional id passed through to events for identification.
   */
  id?: string;

  /**
   * Optional dialog trigger card (e.g., a button).
   *
   * When provided, this card will be used as the dialog trigger.
   * When omitted, the dialog must be controlled via the `open` prop.
   *
   * Wrapped in a DOM element so Radix can attach trigger handlers
   * even when rendered via Pihanga's <Card />.
   */
  trigger?: PiCardRef;

  /**
   * Card to render as the dialog body content.
   */
  content: PiCardRef;

  /**
   * Optional dialog title (rendered in header).
   */
  title?: string;

  /**
   * Optional dialog description (rendered in header below title).
   */
  description?: string;

  /**
   * Controlled open state.
   *
   * When provided, dialog visibility is fully managed externally.
   * When undefined, dialog manages its own state.
   */
  open?: boolean;

  /**
   * Dialog size variant.
   */
  size?: "xs" | "sm" | "md" | "lg" | "xl" | "2xl" | "3xl" | "4xl";

  /**
   * Dialog variant.
   */
  variant?: "modal" | "drawer" | "full";

  /**
   * Desktop variant (defaults to 'modal').
   * On desktop, this variant will be used instead of the main variant.
   */
  desktopVariant?: "modal" | "drawer" | "full";

  /**
   * Mobile variant (defaults to 'drawer').
   * On mobile, this variant will be used instead of the main variant.
   */
  mobileVariant?: "modal" | "drawer" | "full";

  /**
   * Whether clicking outside closes the dialog (default: true).
   */
  dismissible?: boolean;

  /**
   * Hide the X close button (default: false).
   */
  hideClose?: boolean;

  /**
   * Additional CSS classes for the dialog content.
   */
  className?: string;

  /**
   * Optional footer card to render at the bottom of the dialog.
   * When provided, this takes precedence over the default close button.
   */
  footer?: PiCardRef;

  /**
   * Text for the default close button in the footer.
   * Only used when `footer` is not provided.
   * Set to `null` to hide the default close button entirely.
   * @default "Close"
   */
  footerCloseButtonText?: string | null;
};

export type DialogOpenedEvent = {
  id?: string;
};

export type DialogClosedEvent = {
  id?: string;
  /**
   * Reason for closing:
   * - 'user': User dismissed (clicked outside, pressed ESC, clicked X)
   * - 'programmatic': Closed via props.open change
   */
  reason?: "user" | "programmatic";
};

export type DialogOpenChangedEvent = {
  open: boolean;
  id?: string;
};

export type PiDialogEvents = {
  onOpened: DialogOpenedEvent;
  onClosed: DialogClosedEvent;
  onOpenChanged: DialogOpenChangedEvent;
};

import {actionTypesToEvents, registerCardComponent} from "@pihanga2/core";

import {DialogComponent} from "./dialog.component";
import {PI_DIALOG_ACTION, PI_DIALOG_CARD} from "./dialog.types";

export * from "./dialog.types";

registerCardComponent({
  name: PI_DIALOG_CARD,
  component: DialogComponent,
  events: actionTypesToEvents(PI_DIALOG_ACTION),
});
